<?php require '../../../config/bootstrap.php';$u=require_auth();$p=db();$out=['metrics'=>[],'recent'=>[],'device_health'=>[],'chart'=>['labels'=>[],'temperature'=>[],'humidity'=>[]]];foreach(['farms'=>'SELECT COUNT(*) c FROM farms WHERE tenant_id=? AND status="active"','animals'=>'SELECT COUNT(*) c FROM animals WHERE tenant_id=? AND status="active"','devices'=>'SELECT COUNT(*) c FROM devices WHERE tenant_id=? AND status="active"','alerts'=>'SELECT COUNT(*) c FROM alerts WHERE tenant_id=? AND status="open"'] as $k=>$q){$s=$p->prepare($q);$s->execute([$u['tenant_id']]);$out['metrics'][$k]=(int)$s->fetch()['c'];}$s=$p->prepare('SELECT d.name,t.temperature,t.humidity,t.recorded_at FROM telemetry t JOIN devices d ON d.id=t.device_id WHERE t.tenant_id=? ORDER BY t.recorded_at DESC LIMIT 8');$s->execute([$u['tenant_id']]);$out['recent']=$s->fetchAll();$s=$p->prepare('SELECT name,status,last_seen_at,CASE WHEN last_seen_at IS NULL THEN "OFFLINE" WHEN last_seen_at < NOW()-INTERVAL 15 MINUTE THEN "OFFLINE" ELSE "ONLINE" END state FROM devices WHERE tenant_id=? ORDER BY name');$s->execute([$u['tenant_id']]);$out['device_health']=$s->fetchAll();$s=$p->prepare('SELECT DATE_FORMAT(recorded_at,"%d/%m %H:%i") label,ROUND(AVG(temperature),1) temperature,ROUND(AVG(humidity),1) humidity FROM telemetry WHERE tenant_id=? AND recorded_at>=NOW()-INTERVAL 24 HOUR GROUP BY label ORDER BY MIN(recorded_at) LIMIT 48');$s->execute([$u['tenant_id']]);foreach($s as $r){$out['chart']['labels'][]=$r['label'];$out['chart']['temperature'][]=$r['temperature'];$out['chart']['humidity'][]=$r['humidity'];}json_response($out);
